import * as z from "zod/v4";
import { allowAll, defineChannel, hmacSignatureAuth, localDevStrict, loopbackOnly, POST, } from "../../channels.js";
import { withPropagatingBackgroundErrors } from "../../internal/channel-dispatch.js";
import { normalizeIdentity } from "../../internal/continuation-identity.js";
import { isDevMode } from "../../internal/dev-mode.js";
import { attachHostedAdmissionAdapter } from "../../internal/hosted-admission-adapter.js";
import { replayCatchRequest } from "../../internal/hosted-catch.js";
import { AGENT_SDK_CATCH_EVENT_TYPE } from "../../internal/hosted-catch-protocol.js";
import { namedWebhookSecretArchitectureError } from "../../internal/named-webhook-secret.js";
import { isSecretRef } from "../../types.js";
import { buildDefaultPagerDutyEvents } from "./defaults.js";
import { derivePagerDutyWebhookEvents, PAGERDUTY_CHANNEL_KIND } from "./events.js";
import { handlePagerDutyWebhookRequest, PAGERDUTY_SIGNATURE_HEADER, PAGERDUTY_SIGNATURE_PREFIX, PAGERDUTY_SIGNATURE_SEPARATOR, PAGERDUTY_WEBHOOK_SECRET_ENV, } from "./pagerduty-webhook.js";
import { PAGERDUTY_TOKEN_ENV } from "./api.js";
import { PAGERDUTY_USER_ID_ENV, pagerDutySelfUserIdSecretName } from "./self-user.js";
import { pagerDutySecretName, resolvePagerDutySecret } from "./secrets.js";
import { emptyPagerDutyChannelState } from "./state.js";
const pagerDutyChannelOptionsByDefinition = new WeakMap();
export function getPagerDutyChannelOptions(definition) {
    return pagerDutyChannelOptionsByDefinition.get(definition);
}
/**
 * Deployment secrets the channel reads in the guest that must each be set:
 * a named `selfUserIds`, `token`, or `from` secret. `deploy` declares them
 * so an unset one is flagged instead of the agent waking on its own echoes
 * or failing its write-backs.
 */
export function pagerDutyChannelCredentialSecretNames(definition) {
    const options = getPagerDutyChannelOptions(definition);
    if (options === undefined) {
        return [];
    }
    return [
        ...(options.selfUserIds === undefined ? [] : [pagerDutySelfUserIdSecretName(options)]),
        ...(isSecretRef(options.token) ? [options.token.secretName] : []),
        ...(isSecretRef(options.from) ? [options.from.secretName] : []),
    ].filter((name) => name !== undefined);
}
/**
 * Deployment secrets of which at least one must be set: with `selfUserIds`
 * omitted, the agent's user comes from `PAGERDUTY_USER_ID` or is inferred
 * from the channel's token. `deploy` warns when neither is set. A token
 * authored in code always infers, so it needs no warning.
 */
export function pagerDutyChannelSecretAlternatives(definition) {
    const options = getPagerDutyChannelOptions(definition);
    if (options === undefined || options.selfUserIds !== undefined) {
        return [];
    }
    const tokenName = pagerDutySecretName(options.token, PAGERDUTY_TOKEN_ENV);
    if (tokenName === undefined) {
        return [];
    }
    return [
        {
            names: [PAGERDUTY_USER_ID_ENV, tokenName],
            unsetEffect: `the PagerDuty channel cannot tell the agent's own actions apart, so echo skip is off (set ${PAGERDUTY_USER_ID_ENV}, or ${tokenName} to infer it)`,
        },
    ];
}
/**
 * Why a `pagerdutyChannel` cannot deploy onto architecture v2 as authored,
 * or `undefined` when it can: v2 needs a named `webhookSecret` so the
 * control plane can verify `X-PagerDuty-Signature` before any compute starts.
 */
export function pagerDutyChannelArchitectureError(definition) {
    const options = getPagerDutyChannelOptions(definition);
    if (options === undefined) {
        return undefined;
    }
    return namedWebhookSecretArchitectureError({
        option: "pagerdutyChannel webhookSecret",
        webhookSecret: options.webhookSecret,
        envName: PAGERDUTY_WEBHOOK_SECRET_ENV,
        verifies: "X-PagerDuty-Signature",
    });
}
/**
 * The route policy for a PagerDuty v3 webhook whose secret is named: any
 * `v1=` entry of `X-PagerDuty-Signature` must be the body's HMAC under the
 * env var / deployment secret `secretName`, so both of a rotating pair of
 * secrets verify. Being an {@link hmacSignatureAuth} policy, `deploy`
 * writes it into the manifest and the control plane runs the same check
 * at ingestion.
 */
export function pagerDutyWebhookSignatureAuth(secretName) {
    return hmacSignatureAuth({
        header: PAGERDUTY_SIGNATURE_HEADER,
        secret: secretName,
        prefix: PAGERDUTY_SIGNATURE_PREFIX,
        separator: PAGERDUTY_SIGNATURE_SEPARATOR,
    });
}
/**
 * Default route auth for the resolved webhook secret, the same postures as
 * the SCM channels: a named secret is the route policy (and the control
 * plane's catch check); a literal or getter keeps the check in the handler
 * behind `allowAll()`.
 *
 * An omitted `webhookSecret` names `PAGERDUTY_WEBHOOK_SECRET`, so a
 * zero-config channel deploys with the control plane verifying against
 * that deployment secret. While it is unset (a fresh local checkout), the
 * route keeps the no-secret posture: loopback-strict, and `--dev` admits
 * loopback. Both are read per request: channel modules construct at import,
 * and a hosted deployment receives its secrets per request.
 */
function defaultPagerDutyRouteAuth(webhookSecret, usesDefaultSecret) {
    if (isSecretRef(webhookSecret)) {
        const signature = pagerDutyWebhookSignatureAuth(webhookSecret.secretName);
        if (!usesDefaultSecret) {
            return [signature];
        }
        const whileUnset = (request, info) => {
            if (resolvePagerDutySecret(webhookSecret, PAGERDUTY_WEBHOOK_SECRET_ENV) !== undefined) {
                return null;
            }
            return (isDevMode() ? loopbackOnly() : localDevStrict())(request, info);
        };
        return [signature, whileUnset];
    }
    return [allowAll()];
}
export function pagerdutyChannel(options = {}) {
    const routePath = options.path ?? "/";
    // Always named, never read here: it deploys like an authored
    // `{ secretName: "PAGERDUTY_WEBHOOK_SECRET" }` whether or not the shell
    // that runs `deploy` has the value.
    const usesDefaultSecret = options.webhookSecret === undefined;
    const webhookSecret = options.webhookSecret ?? { secretName: PAGERDUTY_WEBHOOK_SECRET_ENV };
    const auth = options.auth ?? defaultPagerDutyRouteAuth(webhookSecret, usesDefaultSecret);
    const channelOptions = { ...options, webhookSecret };
    if (channelOptions.continuation !== undefined) {
        channelOptions.continuation = normalizeIdentity(channelOptions.continuation, PAGERDUTY_CHANNEL_KIND);
    }
    const definition = defineChannel({
        auth,
        state: emptyPagerDutyChannelState(),
        events: { ...buildDefaultPagerDutyEvents(channelOptions), ...options.events },
        onStart: options.onStart,
        onStop: options.onStop,
        meta: {
            kind: PAGERDUTY_CHANNEL_KIND,
            pagerdutyWebhookEvents: derivePagerDutyWebhookEvents(channelOptions),
        },
        routes: [
            POST(routePath, {
                bodySchema: z.unknown(),
                description: "PagerDuty v3 webhook ingress",
                handler: async (request, args) => handlePagerDutyWebhookRequest({ options: channelOptions, request, args }),
            }),
        ],
    });
    pagerDutyChannelOptionsByDefinition.set(definition, channelOptions);
    attachHostedAdmissionAdapter(definition, {
        kind: PAGERDUTY_CHANNEL_KIND,
        prepareArgs: withPropagatingBackgroundErrors,
        dispatch: async ({ channelId, eventType, payload, deliveryId, args }) => {
            // Hosted deliveries are http.request envelopes the control plane
            // already verified with the deployment secret and stamped with the
            // incident's key. Replay into the route handler, which verifies
            // X-PagerDuty-Signature again and runs the echo skip.
            if (eventType !== AGENT_SDK_CATCH_EVENT_TYPE) {
                return Response.json({ ok: false, error: "unsupported_pagerduty_delivery" }, { status: 400 });
            }
            return replayCatchRequest({
                channelId: channelId ?? PAGERDUTY_CHANNEL_KIND,
                deliveryId,
                routes: definition.routes ?? [],
                payload,
                args,
                auth,
            });
        },
    });
    return definition;
}
/** Every mounted `pagerdutyChannel()`, for `agent-sdk pagerduty replay` and `events`. */
export function findPagerDutyChannelTargets(mounts) {
    const targets = [];
    for (const { slug, project } of mounts) {
        for (const channel of project.channels) {
            const meta = channel.definition.meta;
            if (meta?.kind !== PAGERDUTY_CHANNEL_KIND) {
                continue;
            }
            const postRoute = (channel.definition.routes ?? []).find((route) => route.method === "POST");
            targets.push({
                slug,
                channelId: channel.id,
                routePath: postRoute?.path ?? "/",
                events: [...(meta.pagerdutyWebhookEvents ?? [])],
            });
        }
    }
    return targets;
}
